  color: AvatarColor;
}

export interface TagOption {
  id: string;
  label: string;
}

export interface EmissionRow {
  id: string;
  source: string;
  factor: string;
  ownerId: string | null;
  tagIds: string[];
  updatedAt: string | null;
}

