  },
  {
    id: 'r2',
    source: '公務車（汽油）',
    factor: '車用汽油（移）',
    ownerId: 'p2',
    tagIds: ['t-pilot'],
    updatedAt: '2025/09/18',
  },
  {
    id: 'r3',
    source: '鍋爐燃燒',
    factor: '天然氣（固）',
    ownerId: 'p1',
    tagIds: [],
    updatedAt: null,
